                + " AND made_on <= ? ORDER BY id DESC LIMIT 1", String.class, sheetId, person.id(), Date.valueOf(date));
        List<PersonGrade> grades = person.grades();
        if (!logged.isEmpty()) {
            grades = new ArrayList<>();
            for (String g : logged.get(0).split(";")) {
                int at = g.indexOf('@');
