package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: on and the signed-in user are required. */
public class ValidateWatch {
    public void validate(@RequestBody WatchRequest request, Out<WatchChange> change) throws InvalidPersonException {
        if (request == null || request.on() == null) {
            throw new InvalidPersonException("Whether to watch is required");
        }
        String by = request.by() == null ? "" : request.by().trim();
        if (by.isEmpty()) {
            throw new InvalidPersonException("The user watching is required");
        }
        change.set(new WatchChange(request.on(), by));
    }
}
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Starts or stops the user watching the person; starting to watch one already watched, or stopping watching one not
 *  watched, is refused. */
public class ApplyWatch {
    public void apply(@Val Person person, @Val WatchChange change, WatchRepository watches) throws InvalidPersonException {
        boolean done = change.on() ? watches.add(person.sheetId(), person.id(), change.by())
                : watches.remove(person.sheetId(), person.id(), change.by());
        if (!done) {
            throw new InvalidPersonException(change.by() + (change.on() ? " already watches " : " does not watch ")
                    + person.name());
        }
    }
}
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Writes PERSON_WATCHED or PERSON_UNWATCHED to the audit file once the watch is stored. */
public class RecordWatchChanged {
    public void record(@Val Person person, @Val WatchChange change, Audit audit) {
        audit.record((change.on() ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + person.sheetId() + " by="
                + change.by() + " name=" + person.name());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a person of the sheet by id; one not on the sheet is a 404. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository people, Out<Person> person) throws PersonNotFoundException {
        Person found;
        try {
            found = people.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new PersonNotFoundException("No person " + personId);
        }
        person.set(found);
    }
}
